[[ ## document ## ]]
{
  "title": "PBC Request — Riverbend Dental Studio",
  "path": "engagements/riverbend-dental-studio/2024-tax/preparation/pbc-request.docx",
  "document": {
    "blocks": [
      {
        "kind": "heading",
        "level": 1,
        "text": "Riverbend Dental Studio — 2024 Tax Return Preparation"
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Request for Information (PBC)"
      },
      {
        "kind": "paragraph",
        "text": "Dear Riverbend Dental Studio Team,"
      },
      {
        "kind": "paragraph",
        "text": "As we begin preparing your 2024 tax return (Form 1065), we need the following items to complete the engagement. Please provide these by March 15, 2025, to allow sufficient time for review and filing. You can upload documents through the client portal or email them directly to me."
      },
      {
        "kind": "heading",
        "level": 3,
        "text": "1. Financial Statements"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Trial balance as of December 31, 2024",
          "Profit and loss statement for the year ended December 31, 2024",
          "Balance sheet as of December 31, 2024"
        ]
      },
      {
        "kind": "heading",
        "level": 3,
        "text": "2. General Ledger Detail"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "General ledger detail for all accounts (cash, accounts receivable, inventory, fixed assets, loans, equity)",
          "Bank statements for all accounts (all pages) for the full year 2024"
        ]
      },
      {
        "kind": "heading",
        "level": 3,
        "text": "3. Fixed Asset Information"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Fixed asset schedule showing additions, disposals, and accumulated depreciation through December 31, 2024",
          "Invoices/receipts for any equipment, furniture, or leasehold improvements purchased in 2024",
          "Details of any asset disposals or trade-ins during 2024"
        ]
      },
      {
        "kind": "heading",
        "level": 3,
        "text": "4. Loans & Interest"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Loan statements and amortization schedules for all outstanding debt as of December 31, 2024",
          "Form 1098 (mortgage interest) if applicable",
          "Summary of interest paid on all business loans during 2024"
        ]
      },
      {
        "kind": "heading",
        "level": 3,
        "text": "5. Owner/Partner Information"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "K-1 information for each partner (name, address, tax ID, ownership %)",
          "Capital account roll-forward through December 31, 2024",
          "Any partner contributions or distributions during 2024 (dates and amounts)"
        ]
      },
      {
        "kind": "heading",
        "level": 3,
        "text": "6. Payroll & Contractor Info"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Payroll summary by quarter for 2024 (wages, taxes withheld, employer taxes)",
          "Forms 941 for all four quarters of 2024",
          "Form W-3 and all W-2s issued",
          "1099-NEC summaries and copies for any independent contractors paid more than $600 in 2024"
        ]
      },
      {
        "kind": "heading",
        "level": 3,
        "text": "7. Other Income & Deductions"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "All Forms 1099-K, 1099-MISC, or 1099-NEC received for 2024",
          "Credit card processing statements summarizing total fees for the year",
          "Rent statements/lease agreements for any property leased during 2024",
          "Utility bills (electric, water, internet, phone) for all 12 months"
        ]
      },
      {
        "kind": "heading",
        "level": 3,
        "text": "8. Prior Year Return"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Copy of your 2023 Form 1065 and all schedules (if not already on file with our firm)"
        ]
      },
      {
        "kind": "paragraph",
        "text": "If you have any questions about the items above or need additional time, please reach out. Thank you for your prompt attention to this request."
      },
      {
        "kind": "paragraph",
        "text": "Best regards,\nColin Mackey\nStaff Accountant, Tax\nMackey & Associates CPAs"
      }
    ]
  }
}
[[ ## completed ## ]]
